'use strict';
/* Offline presentation prototype. Deliberately no fetch, WebSocket, system bridge or storage. */
const screens=window.SCREENS, $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,primary=false,action='preview')=>`<button type="button" class="${primary?'primary':''}" data-action="${esc(action)}">${esc(text)}</button>`;
const link=(id,text)=>`<a class="tab" href="#${esc(id)}">${esc(text)}</a>`;
const badge=(s,cls='')=>`<span class="badge ${cls}">${esc(s)}</span>`;
const panel=(title,content,meta='',tight=false)=>`<section class="panel"><div class="panel-head"><span>${esc(title)}</span><small>${esc(meta)}</small></div><div class="panel-body${tight?' tight':''}">${content}</div></section>`;
const note=(title,text,cls='')=>`<div class="callout ${cls}"><strong>${esc(title)}</strong> ${esc(text)}</div>`;
const tabs=names=>`<div class="tabs">${names.map((x,i)=>`<button type="button" class="tab ${i?'':'active'}" data-action="tab">${esc(x)}</button>`).join('')}</div>`;
const search=(placeholder='Filter this view…')=>`<input type="search" class="local-filter" placeholder="${esc(placeholder)}" aria-label="${esc(placeholder)}">`;
const row=(title,detail='',value='',icon='◇')=>`<div class="row filterable"><span class="glyph" aria-hidden="true">${icon}</span><div class="grow"><strong>${esc(title)}</strong><small>${esc(detail)}</small></div><span class="value">${esc(value)}</span></div>`;
const list=rows=>rows.map(x=>row(...x)).join('');
const metric=(name,value,detail='',percent=0)=>`<div class="metric"><small>${esc(name)}</small><strong>${esc(value)}</strong>${percent?`<div class="bar" style="--value:${Number(percent)}%"><i></i></div>`:''}<p>${esc(detail)}</p></div>`;
const table=(heads,rows)=>`<table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="filterable">${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const tree=x=>`<pre class="tree">${esc(x)}</pre>`;
function icon(name){const paths={chat:'M4 5h16v11H9l-5 4z',library:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',tasks:'M5 5h14v15H5z M9 3h6v4H9z M8 12h8 M8 16h5',graph:'M12 4v7m0 0-7 7m7-7 7 7 M10 3h4v3h-4z M3 17h4v4H3z M17 17h4v4h-4z',terminal:'M4 6l6 6-6 6 M12 18h8',hardware:'M7 7h10v10H7z M9 3v4m6-4v4M9 17v4m6-4v4M3 9h4m-4 6h4m10-6h4m-4 6h4',settings:'M12 3l2 4 4-1 3 5-3 3 1 4-5 3-3-3-4 1-3-5 3-3-1-4z',source:'M3 6h7l2 3h9v11H3z',camera:'M3 7h5l2-3h4l2 3h5v13H3z M8 13a4 4 0 1 0 8 0a4 4 0 1 0-8 0',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',home:'M3 11l9-8 9 8 M6 9v12h12V9 M10 21v-7h4v7',sound:'M4 9h4l5-5v16l-5-5H4z M17 7q6 5 0 10'};return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.graph}"/></svg>`;}
function spark(seed=1,color='var(--gold)',height=112){let pts=[];for(let i=0;i<65;i++){let y=57+Math.sin(i*.33+seed)*15+Math.sin(i*1.2+seed)*8+(i%19===5?-23:0);pts.push(`${i*10},${y.toFixed(1)}`);}return `<svg class="spark" style="height:${height}px" viewBox="0 0 640 110" preserveAspectRatio="none" aria-label="Illustrative resource history"><path class="chart-grid" d="M0 25H640M0 55H640M0 85H640M80 0V110M240 0V110M400 0V110M560 0V110"/><path d="M${pts.join(' L')}" fill="none" stroke="${color}" stroke-width="2"/></svg>`;}
function planet(){let dots='',lines='';for(let i=0;i<100;i++){let a=i*2.39996,r=120*Math.sqrt((i+.5)/100),x=570+Math.cos(a)*r*1.4,y=155+Math.sin(a)*r;dots+=`<circle cx="${x}" cy="${y}" r="${i%9===0?1.8:.7}" fill="${i%4===0?'#8fb8cc':'#c6a56b'}" opacity=".7"/>`;}for(let i=0;i<7;i++){let x=468+i*32;lines+=`<path d="M${x} 40l95-18v236l-95 19z" fill="${['#8fb8cc','#b3bfad','#c6a56b','#c6a56b','#b78273','#c6a56b','#9fb6bc'][i]}" fill-opacity=".035" stroke="${i>3?'#c6a56b':'#668993'}" stroke-opacity=".6"/>`;}return `<svg viewBox="0 0 900 300" aria-label="Original illustrative information-layer globe"><defs><radialGradient id="sphere"><stop stop-color="#172c32"/><stop offset=".8" stop-color="#0c191d"/><stop offset="1" stop-color="#0b1214"/></radialGradient></defs><g fill="none" stroke="#645338" opacity=".5"><circle cx="570" cy="155" r="142"/><circle cx="570" cy="155" r="164" stroke-dasharray="2 9"/><path d="M370 155h480M570 0v300"/></g><circle cx="570" cy="155" r="125" fill="url(#sphere)" stroke="#c6a56b"/><g stroke="#5f7777" fill="none" opacity=".4"><ellipse cx="570" cy="155" rx="125" ry="37"/><ellipse cx="570" cy="155" rx="125" ry="85"/><ellipse cx="570" cy="155" rx="44" ry="125"/><ellipse cx="570" cy="155" rx="94" ry="125"/></g>${dots}${lines}<g stroke="#c6a56b" opacity=".5"><path d="M675 148L900 117M675 152L900 137M675 156H900M675 160L900 177M675 164L900 197"/></g><circle cx="817" cy="58" r="12" fill="#152021" stroke="#ad915e"/></svg>`;}
function graphSvg(view='Knowledge'){let body='',nodes=[],colors=['#c6a56b','#8fb8cc','#e0b870','#b6bfa0','#baa6cf','#91b9a3'];
 if(view==='Memory'){for(let i=0;i<55;i++){let x=60+i*10,y=200+Math.sin(i*.24)*60;nodes.push([x,y,colors[i%6]]);if(i)body+=`<path d="M${nodes[i-1][0]},${nodes[i-1][1]}L${x},${y}" stroke="#8fb8cc" opacity=".6"/>`;body+=`<ellipse cx="${x}" cy="${y}" rx="9" ry="${35+Math.sin(i*.7)*10}" fill="none" stroke="#c6a56b" opacity=".16"/>`;}body+='<text x="45" y="55" fill="#c6a56b" font-family="monospace" font-size="11">CHRONOLOGY / SELECTED BANK</text><path d="M60 340H605" stroke="#756142"/>';
 }else if(view==='Code'){let labels=['shell.qml','PaneWorkspace','PaneFrame','ShellTheme','ReaderPane','GraphViewer','TerminalPane','ShellApi'];for(let i=0;i<labels.length;i++){let x=i===0?280:80+(i%3)*200,y=i===0?35:100+Math.floor((i-1)/3)*98;body+=`<path d="M320 70L${x+60} ${y}" fill="none" stroke="#756142" opacity=".6"/><rect x="${x}" y="${y}" width="132" height="42" rx="4" fill="#152022" stroke="#a18755"/><text x="${x+66}" y="${y+25}" text-anchor="middle" fill="#ddd6c5" font-family="monospace" font-size="11">${labels[i]}</text>`;}
 }else{for(let j=0;j<6;j++){let a=j*Math.PI/3-.9,cx=340+Math.cos(a)*150,cy=205+Math.sin(a)*140;nodes.push([cx,cy,colors[j],8]);body+=`<path d="M340 205L${cx} ${cy}" stroke="${colors[j]}" opacity=".65"/>`;for(let k=0;k<11;k++){let b=k*2.4+j,x=cx+Math.cos(b)*(24+k*3),y=cy+Math.sin(b)*(22+k*2.3);nodes.push([x,y,colors[j],2.4]);body+=`<path d="M${cx} ${cy}L${x} ${y}" stroke="${colors[j]}" opacity=".32"/>`;}body+=`<text x="${cx}" y="${cy-48}" text-anchor="middle" fill="${colors[j]}" font-family="monospace" font-size="10">${['KNOWLEDGE','AGENT','TASK','RUNBOOK','SKILL','TOOL'][j]}</text>`;}body+='<circle cx="340" cy="205" r="19" fill="#262a21" stroke="#c6a56b"/><text x="340" y="209" text-anchor="middle" fill="#efcf91" font-family="monospace" font-size="9">ROOT</text>';}
 nodes.forEach(([x,y,c,r])=>{body+=`<circle cx="${x}" cy="${y}" r="${r||2}" fill="${c}"/>`;});return `<svg viewBox="0 0 700 410" aria-label="Illustrative ${esc(view)} diagram, not a live graph"><g stroke="#66563b" opacity=".16" fill="none"><circle cx="340" cy="205" r="190"/><circle cx="340" cy="205" r="140"/><path d="M25 205H675M340 12V398"/></g>${body}</svg>`;
}
const agents=[['Computer','Executive · user-facing conversation','Ready','◎'],['Alexandria','Curator · knowledge maintenance','Available','▤'],['Darwin','Researcher · investigation','Available','◇'],['Heimdall','Guardian · audit and review','Available','⬡']];
const taskRows=[['Index selected Sources','Alexandria','Event','Queued','—'],['Review proposed links','Heimdall','Manual','Needs review','—'],['Compare retrieval strategies','Darwin','Manual','Running','02:14'],['Prepare project summary','Computer','Manual','Completed','Receipt']];
const codeSample=`<span class="comment">// Existing shell composition, not a second window manager.</span>\n<span class="kw">PaneWorkspace</span> {\n    id: paneWorkspace\n    shellApi: root.shellApi\n    targetScreens: root.workspaceScreens\n    monitoringAllowed: !root.lockController.active\n}\n\n<span class="kw">PaneFrame</span> {\n    title: <span class="str">"Reader"</span>\n    theme: shellApi.theme\n    <span class="comment">// Native compositor owns movement, focus and geometry.</span>\n    onMoveRequested: window.startSystemMove()\n}\n\n<span class="comment">// Theme tokens change paint; they do not change authority.</span>`;
const builders={};
builders.desktop=()=>`<div class="stack"><div class="columns"><div class="stack">${panel('Command overview',`<div class="hero">${planet()}<div class="hero-copy"><div class="eyebrow">CONTEXT / SYSTEM / ACTION</div><h2>A composed<br>workspace.</h2><p>Knowledge, execution and desktop tools, with one clear place for each.</p></div><div class="hero-tag">ILLUSTRATIVE DATA LAYERS · NOT LIVE TELEMETRY</div></div>`,'Surface composition',true)}<div class="metrics">${metric('CPU','12%','Illustrative sample',12)}${metric('MEMORY','18 / 96','GiB · sample',19)}${metric('ACTIVE TASKS','4','One runtime owner')}${metric('REVIEW QUEUE','1','One pending change')}</div></div><div class="stack">${panel('Agent identities',list(agents),'From existing identity model',true)}${panel('Workspace',list([['Knowledge workspace','Reader · Knowledge · Graph','Open','▤'],['Development workspace','Source · Terminal · Code graph','Open','⌘']]),'Native composition',true)}</div></div><div class="columns equal">${panel('Task activations',table(['Outcome','Agent','Trigger','State','Elapsed'],taskRows),'Illustrative queue',true)}${panel('Recent receipts',list([['Knowledge update committed','Revision and affected refs are recorded.','Completed','✓'],['Model configuration unchanged','A preview never changes model residency.','Read only','◇'],['Desktop theme package created','Obsidian Gold remains a staged preview.','Staged','▣']]),'No inferred success',true)}</div></div>`;
builders.chat=()=>`<div class="columns"><div class="stack">${panel('Conversation',`<div class="toolbar">${button('New conversation')}<span class="grow"></span>${badge('COMPUTER / EXECUTIVE')}<small>Today · sample</small></div><div class="chat-thread"><div class="message user"><div class="who">YOU</div>Show me the proposed theme changes without applying them.</div><div class="message"><div class="who">COMPUTER</div>The package keeps the current pane identities and uses the existing palette owner. The preview includes the shell, knowledge tools and the desktop controls that still need integration.<div class="receipt">Read-only design review · no system changes</div></div><div class="message"><div class="who">PROPOSED NEXT ACTION</div>Review the affected files and native integration boundaries before activating the theme.<div class="toolbar" style="margin-top:12px">${button('Open change plan',true,'spec')}${link('appearance','Inspect theme')}</div></div></div><div class="composer"><input aria-label="Sample conversation composer" placeholder="Ask Computer… (preview only)">${button('Send',true)}${button('Stop')}<small>Explicit actions.<br>Traceable receipts.</small></div>`,'Existing conversation owner')}${note('Trace, not theatre.','Only actual supplied context and Tool results may drive activity indicators.')}</div><div class="stack">${panel('Voice mode',list([['Wake word','Existing speech owner','Computer','◉'],['Microphone','Example state: not capturing','Idle','♩'],['Spoken reply','Existing character voice','HAL','≈']]),'No new audio pipeline',true)}${panel('Context',`<div class="metrics" style="grid-template-columns:1fr 1fr">${metric('INPUT','8.2k','Illustrative tokens')}${metric('BUDGET','64k','Model-dependent')}</div><div class="annotation">Knowledge refs, Tool-return refs and turn identity belong here. A glowing indicator is never a completion receipt.</div>`)}${panel('Controls',`<div class="stack">${button('Mute speech')}${button('Context details')}${button('Review Tool receipts')}</div>`)}</div></div>`;
builders.library=()=>`<div class="stack"><div class="toolbar">${search('Search Tasks, paired Tools and Skills, or Agents…')}${button('Filter')}</div>${tabs(['Tasks','Tools + Skills','Agents'])}<div class="columns"><div>${panel('Available outcomes',list([['Research a defined question','Task · scoped question and acceptance criteria','TASK','◇'],['Curate selected evidence','Task · immutable Source to proposed Articles','TASK','▤'],['Inspect system health','Task · read-only host observations','TASK','▦'],['Review knowledge changes','Task · exact proposals and revisions','TASK','✓'],['Summarize a project','Task · existing selected context','TASK','⌘']]),'Open definitions in Reader',true)}</div><div class="stack">${panel('Selected definition',`<div class="tag-line">${badge('TASK')} ${badge('READ ONLY','blue')}</div><h2>Research a defined question</h2><p class="muted" style="margin-top:14px">A reusable outcome and its acceptance criteria. The procedural path remains Task → Runbook → Skill → Tool.</p><div class="annotation">This catalog is not an execution grant.</div><div class="toolbar" style="margin-top:16px">${link('reader','Open in Reader')}${button('Inspect bindings')}</div>`)}${panel('Agent catalog',list(agents),'Canonical roles',true)}</div></div></div>`;
builders.tasks=()=>`<div class="stack"><div class="queue-badges">${metric('QUEUED','2','Waiting for admission')}${metric('RUNNING','1','Active execution')}${metric('REVIEW','1','Owner attention')}${metric('COMPLETED','8','Historical samples')}</div><div class="toolbar">${search('Filter by outcome, Agent, trigger or activation…')}${button('Create activation',true)}</div>${panel('Activations',table(['Outcome','Agent','Trigger','Runtime state','Elapsed'],taskRows),'Runtime is separate from definitions',true)}<div class="columns">${panel('Selected activation',`<div class="toolbar">${badge('RUNNING','green')}<span class="mono muted">Sample activation · 02:14</span></div><h2>Compare retrieval strategies</h2><p style="margin-top:12px">The runtime records each admitted step and its returned evidence. A Task definition remains reusable independently of this activation.</p><div class="toolbar" style="margin-top:18px">${button('Open Task definition')}${button('View trace')}${button('Cancel activation')}</div>`)}${panel('Execution contract',list([['Agent','Darwin / Researcher','Assigned','◇'],['Runbook','Existing procedure','Bound','▤'],['Model','Current admitted model','Unchanged','▦'],['Completion','Verified outcome + receipt','Required','✓']]),'',true)}</div></div>`;
builders.reviews=()=>`<div class="columns"><div class="stack">${panel('Review queue',list([['Revise an architecture note','1 Article · 2 additions · 1 removal','Selected','▤'],['No other pending proposals','The queue is a projection of the Review owner.','','✓']]),'Illustrative proposal',true)}${panel('Revision comparison',`<div class="toolbar">${badge('BASE r17')}${badge('PROPOSED r18')}<span class="grow"></span>${button('Evidence')}</div><pre class="code"><span class="diff-remove">- Every pane defines its own colors.</span><span class="diff-add">+ One palette supplies semantic colors to shared controls.</span><span class="diff-add">+ A theme changes presentation without changing execution ownership.</span>\nUnchanged: native windows retain compositor geometry.\nUnchanged: the Reader remains the single document viewer.</pre>`)}${note('Revision guard.','If the Article changed after this proposal, approval becomes unavailable until the comparison is refreshed.')}</div><div class="stack">${panel('Evidence & scope',list([['Affected Article','Architecture / Shell','1 ref','▤'],['Evidence','Theme package specification','2 refs','◇'],['Relationship changes','None in this sample','0','⌘'],['Writer','Existing revision-checked owner','Bound','✓']]),'',true)}${panel('Decision',`<p>Approve only the displayed revision. Rejection removes this proposal, not unrelated work.</p><div class="toolbar" style="margin-top:18px">${button('Accept revision',true)}${button('Reject')}${button('Refresh')}</div>`)}${note('Not an AI confidence meter.','Approval is a deliberate action with a recorded outcome.','info')}</div></div>`;
builders.reader=()=>`<div class="columns"><div class="stack">${panel('Article / Architecture',`<div class="toolbar">${badge('KNOWLEDGE')}${badge('r18')}<span class="grow"></span>${button('Edit')}${button('Checkouts')}</div><article class="reader-copy"><div class="eyebrow">ARCHITECTURE / SHELL</div><h2>One shell. One visual authority.</h2><p>The theme is a presentation package. It defines material, color, spacing and typography without taking ownership of windows, model residency or execution.</p><h3>Native panes</h3><p>PaneWorkspace registers each pane once. The compositor owns placement, focus and interactive resize. The frame contains only internal chrome and content controls.</p><h3>Knowledge and evidence</h3><p>The Reader is the single Article and Source viewer. Edits pass through the existing revision-checked writer. Provider-managed historical records remain clearly read-only.</p><h3>Theme activation</h3><p>Validate a preset, show the affected surfaces, apply atomically and keep a rollback record. A style change must not restart an active task or alter a device configuration.</p></article>`,'Illustrative Article, not a live edit')}</div><div class="stack">${panel('Docked Knowledge',tree('Architecture\n ├─ Harness\n └─ Shell\n    ├─ Surfaces\n    ├─ Theme contract\n    └─ Native panes'))}${panel('Links and provenance',list([['Shell design contract','Existing owner document','Outgoing','↗'],['Theme integration plan','Package specification','Outgoing','↗'],['Implementation source','Exact files in pane map','Evidence','◇']]),'',true)}${panel('Record state',`<p class="muted">Article · revision checked · editable through owner</p><div class="annotation">Binary Sources, truncated previews and Hindsight-managed records use explicit alternate states.</div>`)}</div></div>`;
builders.knowledge=()=>`<div class="columns"><div class="stack">${panel('Knowledge tree',`${search('Filter Articles and exact references…')}<div style="margin-top:16px">${tree('◎ Computer / Executive\n  ├─ Architecture\n  │  ├─ Harness\n  │  └─ Shell\n  ├─ Projects\n  │  └─ Obsidience Themes\n  ├─ Runbooks\n  └─ Preferences\n\n▤ Alexandria / Curator\n  ├─ Assigned knowledge\n  └─ Maintenance procedures\n\n◇ Darwin / Researcher\n  └─ Assigned research\n\n⬡ Heimdall / Guardian\n  └─ Audit procedures')}</div>`,'Names supplied by navigation projection')}</div><div class="stack">${panel('Selected Article',`<div class="tag-line">${badge('KNOWLEDGE')} ${badge('EXACT REF')}</div><h2>Architecture / Shell</h2><p style="margin-top:14px" class="muted">Hierarchy and agent assignment come from the current projection. The tree does not invent categories or grant access.</p><div class="toolbar" style="margin-top:16px">${link('reader','Open Reader')}${link('graph-knowledge','Locate in Graph')}</div>`)}${panel('Placement',`<p>Dock into the existing Reader, collapse to its rail, or detach into one native pane.</p><div class="toolbar" style="margin-top:16px">${button('Dock left')}${button('Dock right')}${button('Detach')}</div>`)}${note('One identity.','Tree, Reader and Graph select the same Article reference, not copied representations with separate state.')}</div></div>`;
builders.graph=s=>`<div class="columns" style="grid-template-columns:minmax(0,2fr) minmax(260px,1fr)"><div class="stack"><div class="toolbar">${link('graph-knowledge','Knowledge')}${link('graph-memory','Memory')}${link('graph-code','Code')}<span class="grow"></span>${button('Fit view')}${button('Focus selection')}</div>${panel(s.data.view+' graph',`<div class="graph-visual">${graphSvg(s.data.view)}<div class="graph-caption"><span>ILLUSTRATIVE TOPOLOGY / NOT LIVE DATA</span><span>SAME CANONICAL VIEWER</span></div></div>`,'Viewer projection',true)}${note('Paint only.','The native implementation receives the existing renderer’s frames. This static design illustration is not a replacement graph engine.')}</div><div class="stack">${panel('Inspector',`<div class="tag-line">${badge(s.data.view.toUpperCase())}</div><h2>${s.data.view==='Memory'?'Selected historical record':s.data.view==='Code'?'PaneWorkspace.qml':'Architecture / Shell'}</h2><p style="margin-top:14px" class="muted">${s.data.view==='Memory'?'Show bank, source time, exact record ID and supported provenance. Provider-managed data stays read-only.':s.data.view==='Code'?'Show the selected file or symbol and relationships actually returned by the code provider.':'Show Article kind, exact reference, revision, evidence and links supplied by the knowledge projection.'}</p><div class="toolbar" style="margin-top:18px">${link('reader','Open record')}${button('Focus')}</div>`)}${panel('Visible layers',list(s.data.view==='Knowledge'?[['Knowledge','Article type','Visible','◇'],['Agent','Article type','Visible','◎'],['Task / Runbook','Article types','Visible','▤'],['Skill / Tool','Article types','Visible','⌘']]:[['Selected provider',s.data.view,'Connected','◇'],['Activity overlay','Observed public events only','Enabled','≋'],['Relationship labels','Returned edges only','Enabled','↗']]),'',true)}${panel('Accessibility',`<p class="muted">A synchronized searchable record list provides a keyboard alternative to the visual graph.</p>`)}</div></div>`;
builders.source=()=>`<div class="columns"><div class="stack">${panel('Source trees',`${search('Filter paths, evidence and system snapshots…')}<div style="margin-top:15px">${tree('System\n ├─ Hardware inventory\n ├─ Display topology\n └─ Installed software\nKnowledge\n ├─ Architecture\n └─ Projects\nEvidence\n ├─ Raw captures\n ├─ Imported documents\n └─ Reviewed records\nProject\n ├─ shell / theme / obsidian-gold\n ├─ shell / qml\n └─ ui / src')}</div>`,'Provenance explorer')}</div><div class="stack">${panel('Selected Source',`<div class="tag-line">${badge('SOURCE')} ${badge('IMMUTABLE','blue')}</div><h2>Shell interface inventory</h2><div class="permission-details"><dt>Storage</dt><dd>Local evidence</dd><dt>Identity</dt><dd>Exact source key</dd><dt>Media type</dt><dd>application/json</dd><dt>Observation</dt><dd>Recorded timestamp</dd><dt>Coverage</dt><dd>Bounded snapshot, not a live filesystem</dd></div><div class="toolbar">${link('reader','Read Source')}${button('Inspect provenance')}</div>`)}${note('Not a file manager.','General files, trash, transfers and overwrite conflicts belong to a maintained native filesystem application.','info')}${panel('Agent checkouts',list([['Alexandria','Knowledge maintenance','Not checked out','▤'],['Darwin','Research context','Not checked out','◇'],['Heimdall','Audit context','Not checked out','⬡']]),'Explicit scoped context',true)}</div></div>`;
builders.models=()=>`<div class="stack">${note('Capacity is not a promise.','Residency, context limits and measurements come from the existing model owner. Previewing this theme changes none of them.')}<div class="columns"><div class="stack">${panel('Task-capable models',list([['Current Executive model','Local runtime · existing assignment','Loaded','▦'],['Optional task model','Available only after admission','Not loaded','◇'],['Embedding model','Dedicated existing service','Separate owner','≋']]),'Illustrative capacity states',true)}${panel('Selected configuration',`<div class="metrics" style="grid-template-columns:1fr 1fr">${metric('CONTEXT','64k','Configured limit, sample')}${metric('OUTPUT LIMIT','4k','Per-request cap, sample')}</div><div class="setting-row"><div><strong>Allowed devices</strong><small>Hardware-slot policy remains authoritative.</small></div><select aria-label="Sample GPU permission"><option>Keep current assignment</option><option>CPU only</option></select></div><div class="toolbar">${button('Review changes',true)}${button('Cancel')}</div>`)}</div><div class="stack">${panel('Measured performance',`<div class="metrics" style="grid-template-columns:1fr 1fr">${metric('PREFILL','—','No matching measurement')}${metric('DECODE','—','No matching measurement')}</div><p class="muted" style="margin-top:15px">Run a deliberate benchmark only after reviewing GPU contention, model state and the proposed workload.</p><div class="toolbar" style="margin-top:15px">${button('Inspect benchmark plan')}</div>`)}${panel('Ownership',list([['Residency','One admission owner','Preserved','▦'],['Realtime devices','Settings / AI & Voice','Separate','♩'],['Physical GPU telemetry','Hardware pane','Read only','⌘']]),'',true)}</div></div>`;
builders.hardware=()=>`<div class="stack"><div class="toolbar">${tabs(['Summary','CPU','Memory','GPUs','Storage','Network'])}<span class="grow"></span>${link('hardware-processes','Processes')}</div><div class="metrics">${metric('CPU','12%','Illustrative sample',12)}${metric('MEMORY','18 GiB','of 96 GiB · sample',19)}${metric('GPU','8%','Selected adapter · sample',8)}${metric('NETWORK','2.4 MB/s','Receive · sample')}</div><div class="columns equal">${panel('CPU history',spark(3)+`<div class="toolbar"><small>60-second bounded presentation history</small><span class="grow"></span>${badge('SAMPLE DATA')}</div>`,'Percent · illustrative')}${panel('Memory history',spark(7,'var(--information)')+`<small>Unavailable samples remain gaps, never zero.</small>`,'Selected resource')}</div><div class="columns equal">${panel('GPU devices',list([['Display / rendering adapter','Desktop and graph presentation','Active','▦'],['Model compute adapter','Existing residency assignments','Reserved','▦'],['Integrated graphics','Auxiliary display workload','Active','▦']]),'No reassignment on theme change',true)}${panel('Filesystem capacity',list([['System volume','Current filesystem identity','Sample 28%','▤'],['Model storage','Separate capacity reading','Sample 43%','▤'],['Removable media','None assumed','Unavailable','◇']]),'Read-only',true)}</div></div>`;
builders.processes=()=>`<div class="stack"><div class="toolbar">${search('Filter process name or PID…')}${button('Sort CPU')}${button('Sort memory')}${link('hardware','Performance')}</div>${note('Read-only process view.','The monitor cannot terminate processes. CPU and memory values below are illustrative.')} ${panel('Processes',table(['PID','Process','CPU','Memory','Identity'],[['1042','obsidience shell','1.4%','248 MiB','start time verified'],['1328','graph presenter','3.8%','632 MiB','start time verified'],['2140','harness','0.9%','428 MiB','start time verified'],['3075','terminal','0.2%','86 MiB','start time verified'],['4452','browser','4.1%','1.4 GiB','start time verified'],['4817','editor','1.1%','410 MiB','start time verified']]),'Bounded census',true)}${panel('Selected process',list([['Process identity','PID + start time guard','Required','◇'],['CPU sample','Delta over observation interval','Read only','≋'],['Owner','Existing hardware monitor','No new daemon','⌘']]),'',true)}</div>`;
builders.camera=()=>`<div class="columns"><div class="stack">${panel('Video preview',`<div class="camera-frame"><div class="camera-center"><span class="glyph">${icon('camera')}</span><h2>Preview closed</h2><p style="margin-top:12px">No live image is included in this design.<br>No camera or microphone is acquired.</p></div></div>`,'VIDEO ONLY',true)}<div class="toolbar">${button('Open preview',true)}${button('Retry')}${link('settings-ai-voice','Device settings')}</div></div><div class="stack">${panel('Selected device',list([['Camera','Identity supplied by existing camera owner','Selected','◇'],['Preview state','Closed in this sample','Not capturing','○'],['Audio','Owned by Realtime, never this pane','Separate','♩']]),'',true)}${note('Privacy boundary.','Closing this pane releases its preview. It must not power off a camera being used elsewhere or silently stop another application’s call.','info')}${panel('Failure state',`<p class="muted">Show device-in-use, disconnected and permission errors separately. Retry changes the preview subscription only.</p>`)}</div></div>`;
builders.media=()=>`<div class="stack"><div class="toolbar">${link('media','Library')}${link('media-discover','Discover')}<span class="grow"></span>${search('Search your library…')}</div><div class="columns"><div class="card-grid">${['ORBITAL ARCHIVE','QUIET SIGNALS','DISTANT WORLDS'].map((t,i)=>`<div class="card filterable"><div class="poster ${i===1?'two':i===2?'three':''}">${t}</div><h3>${['Orbital archive','Quiet signals','Distant worlds'][i]}</h3><p>Illustrative library entry<br>${i===0?'Series · season 1':'Film · sample metadata'}</p><div style="margin-top:14px">${button('Select')}</div></div>`).join('')}</div><div class="stack">${panel('Playback target',`<h2>Living-room display</h2><p class="muted" style="margin-top:10px">Illustrative target. Actual target identity comes from the existing media owner.</p><div class="setting-row"><div><strong>Resume position</strong><small>Use the saved position only for the selected media identity.</small></div><span class="mono gold">12:42</span></div><div class="toolbar">${button('Resume on target',true)}${button('Play from start')}</div>`)}${panel('Command receipt',list([['Request','No command has been sent','None','◇'],['Playback','Await the matching owner observation','Not verified','○'],['Controls','Pause / resume / stop / seek','Explicit','▷']]),'',true)}</div></div>${panel('Now playing',`<div class="toolbar"><span class="glyph">▷</span><div class="grow"><h3>Orbital archive / illustrative selection</h3><small>Sample playback position · not a live player</small></div>${button('Pause')}${button('Stop')}${button('Check receipt')}</div><input type="range" min="0" max="100" value="28" aria-label="Illustrative seek position" style="width:100%">`,'Existing media/TV owner')}</div>`;
builders['media-discover']=()=>`<div class="stack"><div class="toolbar">${link('media','Library')}${link('media-discover','Discover')}<span class="grow"></span>${badge('METADATA ≠ SOURCE AVAILABILITY')}</div><div class="columns">${panel('Find a title',`${search('Search title and year…')}<div style="margin-top:16px">${list([['Orbital archive','Series · sample year · metadata match','Selected','▤'],['Orbital archive: field notes','Related documentary · sample result','Metadata','◇']])}</div><div class="setting-row"><div><strong>Season / episode</strong><small>Bind source selection to exact episode identity.</small></div><select aria-label="Sample episode"><option>Season 1 · Episode 1</option><option>Season 1 · Episode 2</option></select></div>${button('Find eligible sources',true)}`)}<div class="stack">${panel('Readiness',list([['Metadata match','Title identity resolved','Matched','✓'],['Registered source','Source identity not yet selected','Required','◇'],['Acquisition readiness','Read actual service result','Unknown','○'],['Playback eligibility','Separate from search success','Not verified','▷']]),'',true)}${note('Deliberate acquisition.','Do not turn a search result into an automatic download. Review source, permissions and the existing acquisition contract.')}</div></div></div>`;
builders.applications=()=>`<div class="stack"><div class="toolbar">${search('Search installed applications…')}${button('Search packages')}${link('application-updates','Updates')}</div><div class="columns"><div>${panel('Installed applications',list([['Web browser','Registered desktop handler','Launch','◎'],['Terminal','Independent native recovery terminal','Launch','›_'],['Code editor','Native external application','Launch','⌘'],['File manager','General filesystem and trash','Launch','▤'],['Media player','Existing player / MPRIS participant','Launch','▷'],['Archive manager','Maintained native application','Launch','▣']]),'Illustrative app catalog',true)}</div><div class="stack">${panel('Selected application',`<span class="glyph">${icon('source')}</span><h2 style="margin-top:16px">File manager</h2><p class="muted" style="margin-top:12px">A normal native application. Obsidience launches and themes it through supported desktop integration instead of mirroring its window.</p><div class="permission-details"><dt>Source</dt><dd>Installed package metadata</dd><dt>Launch</dt><dd>Exact desktop ID</dd><dt>Removal</dt><dd>PackageKit transaction</dd></div><div class="toolbar">${button('Launch',true)}${button('Package details')}</div>`)}${note('Existing machinery.','The current Applications pane already searches, installs and removes through its PackageKit adapter. Missing update UX should extend that owner.')}</div></div></div>`;
builders.updates=()=>`<div class="stack">${note('Review before applying.','This is a proposed extension of Applications, not a second package manager. No packages are changed by the preview.')}<div class="metrics">${metric('UPDATES','12','Illustrative count')}${metric('DOWNLOAD','248 MB','Illustrative estimate')}${metric('RESTART','Review','Actual packages decide')}${metric('TRANSACTION','Not started','No action sent')}</div>${panel('Proposed transaction',table(['Package group','Change','Download','Consequence'],[['Desktop libraries','Full system update','68 MB','Restart affected applications'],['Browser','Security update','124 MB','Restart browser'],['System libraries','Full system update','56 MB','Review service/session restart'],['Protected graphics stack','Not assumed by design','—','Keep existing package policy']]),'Sample transaction',true)}<div class="toolbar">${button('Review full transaction',true)}${button('Refresh metadata')}${button('History')}<span class="grow"></span>${badge('NO PARTIAL ARCH UPGRADES')}</div>${panel('Transaction lifecycle',list([['Resolve','Dependencies and conflicts','Pending','◇'],['Authorize','Native package/authentication workflow','Required','⬡'],['Apply','Owned by PackageKit','Not started','▦'],['Verify','Recorded result, errors and restart guidance','Required','✓']]),'',true)}</div>`;
builders.terminal=()=>`<div class="stack">${tabs(['Local Console','Active Trace','Agent Canvas'])}${panel('Local console',`<pre class="code" style="min-height:365px"><span class="comment"># Illustrative terminal content. No commands are executed.</span>\n<span class="str">user@obsidience</span>:~/Projects/obsidience$ git status --short\n?? obsidience/shell/theme/obsidian-gold/\n\n<span class="str">user@obsidience</span>:~/Projects/obsidience$ tree shell/theme\nshell/theme\n├── palette.json              <span class="comment"># active palette, unchanged</span>\n├── catalog.json\n└── obsidian-gold\n    ├── palette.json          <span class="comment"># compatible, inactive preset</span>\n    ├── tokens.json\n    ├── preview\n    ├── designs\n    └── docs\n\n<span class="comment"># Existing tmux session remains the terminal's owner.</span>\n<span class="str">user@obsidience</span>:~/Projects/obsidience$ <span class="gold">▌</span></pre>`,'Persistent session identity',true)}<div class="toolbar">${button('Copy selection')}${button('Paste')}${button('Session details')}<span class="grow"></span>${badge('TMUX / EXISTING SESSION')}</div>${note('No hidden restart.','A theme must not recreate the terminal, reset a running process or detach a coding-agent session.')}</div>`;
builders.development=()=>`<div class="stack"><div class="tile-layout" style="min-height:440px;grid-template-columns:1fr 2fr 1.2fr"><div class="tile"><div class="eyebrow">SOURCE / NATIVE PANE</div>${tree('shell/\n  theme/\n    obsidian-gold/\n      palette.json\n      tokens.json\n  qml/\n    api/\n    workspace/\n    panes/')}<small>Existing Source explorer</small></div><div class="panel">${panel('Reader or native editor',`<pre class="code">${codeSample}</pre>`,'One writer',true)}</div><div class="tile"><div class="eyebrow">GRAPH / CODE VIEW</div><div style="height:300px">${graphSvg('Code')}</div><small>Canonical graph viewer</small></div></div>${panel('Terminal / Active trace',`<pre class="code" style="min-height:135px">[preview] Selected workspace composition\n[owner] Source and Reader keep existing identities\n[owner] External editor remains a native window\n[owner] Hyprland retains focus, z-order and tile geometry\n[preview] No build or shell command has been executed</pre>`,'Existing tmux session',true)}</div>`;
builders.tft=()=>`<div class="columns"><div class="stack">${panel('Observed board',`<div class="toolbar" style="padding:14px;margin:0">${badge('SAMPLE ROUND 3-2')}<span class="grow"></span>${badge('READ-ONLY LEDGER','blue')}</div><div class="board">${Array.from({length:21},(_,i)=>`<div class="hex ${[3,5,8,11,15,17].includes(i)?'filled':''}">${[3,5,8,11,15,17].includes(i)?'UNIT '+(i+1):'·'}</div>`).join('')}</div>`,'No gameplay actions',true)}${panel('Latest observations',table(['Field','Observed value','Age','Source'],[['Round','3-2','Sample','Existing recorder'],['Gold','42','Sample','Ledger observation'],['Board','6 units','Sample','Ledger observation'],['Decision','Historical selection','Sample','Recorded receipt']]),'Illustrative rows',true)}</div><div class="stack">${panel('Ledger state',list([['Observation freshness','Timestamp must be visible','Sample','◷'],['Reconstruction','Known vs uncertain state','Separate','◇'],['Recommendations','Historical reasoning summary only','Read only','▤']]),'',true)}${note('Do not infer live state.','The theme uses the existing ledger view. It never plays the game, starts training or invents a second recorder.','info')}</div></div>`;
function settingControl(spec){const [type,value]=spec.split(/:(.*)/s);if(type==='toggle')return `<button type="button" class="toggle" aria-label="Toggle preview setting" aria-pressed="${value==='on'}" data-action="toggle"></button>`;if(type==='select')return `<select aria-label="Preview setting">${value.split('|').map(x=>`<option>${esc(x)}</option>`).join('')}</select>`;if(type==='range')return `<input type="range" min="0" max="100" value="${Number(value)}" aria-label="Preview amount">`;if(type==='button')return button(value);return `<span class="mono gold">${esc(value)}</span>`;}
builders.settings=s=>`<div class="columns"><div class="stack">${panel(s.data.section,`<p class="muted" style="margin-bottom:10px">${esc(s.data.intro)}</p>${s.data.controls.map(([title,desc,value])=>`<div class="setting-row"><div><strong>${esc(title)}</strong><small>${esc(desc)}</small></div>${settingControl(value)}</div>`).join('')}`,'Settings section, not a new pane')}<div class="toolbar">${button(s.status==='Existing'?'Review changes':'Preview integration',true)}${button('Reset preview')}<small>Controls demonstrate interaction only.</small></div></div><div class="stack">${panel('Service boundary',`<div class="eyebrow">OWNER</div><p style="margin-top:12px">${esc(s.owner)}</p><div class="annotation">${esc(s.acceptance)}</div>`)}${panel('Related settings',`<div class="stack">${link('appearance','Obsidience Themes')}${link('settings-workspace','Workspace')}${link('accessibility','Accessibility')}${link('privacy','Privacy')}</div>`)}${note('No silent writes.','Actual native controls must display pending, applied and failed states from the owning service.')}</div></div>`;
builders['workspace-settings']=()=>`<div class="columns"><div class="stack">${panel('Surface tiling',`<div class="toolbar">${button('Main Surface',true,'tab')}${button('Graph Surface',false,'tab')}${button('Strip Surface',false,'tab')}</div><div class="tile-layout"><div class="tile"><span>Source</span><small>1 × 2</small></div><div class="tile wide"><span>Reader / editor</span><small>2 × 2</small></div><div class="tile"><span>Computer</span><small>1 × 2</small></div><div class="tile wide"><span>Terminal</span><small>2 × 1</small></div><div class="tile wide"><span>Graph</span><small>2 × 1</small></div></div><div class="annotation">Illustrative layout. Native compositor retains exact geometry and shared cuts.</div>`)}${panel('Shared geometry',`<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('GRID','10 px','Existing contract')}${metric('SEAM GAP','5 px','Compositor-owned')}${metric('PLACEMENT','One','Record per native pane')}</div>`)}</div><div class="stack">${panel('Tile behavior',`<div class="setting-row"><div><strong>Expand / contract limit</strong><small>Native shared-cut movement.</small></div><span class="mono gold">25%</span></div><div class="setting-row"><div><strong>OLED seam drift</strong><small>Existing compositor policy. Theme adds no clock.</small></div>${settingControl('toggle:off')}</div><div class="setting-row"><div><strong>Preserve layout</strong><small>A style change never relocates panes.</small></div><span class="mono gold">Required</span></div>`)}${panel('Native shortcuts',list([['Meta + Arrow','Resize current tile','','⌘'],['Ctrl + Meta + Arrow','Translate current tile','','⌘'],['Meta + Shift + Arrow','Move to mapped Surface','','⌘']]),'Existing bindings',true)}</div></div>`;
builders.appearance=()=>`<div class="stack"><div class="columns"><div class="stack">${panel('Obsidience Themes',`<div class="theme-preview"><div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div></div><div><strong>OBSIDIAN GOLD</strong><div class="mini-graph">◎</div><div class="mini-line"></div></div><div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div></div></div><div class="toolbar" style="margin-top:18px"><div class="grow"><h2>Obsidian Gold</h2><small>Matte cassette futurism · 0.1.0 · first design package</small></div>${badge('STAGED / NOT APPLIED')}</div><div class="toolbar">${button('Review affected surfaces',true,'spec')}${button('Preview only')}${button('Restore previous theme')}</div>`,'One active palette authority')} ${panel('Material and palette',`<div class="swatches">${[['#090d0e','Canvas'],['#0d1113','Surface'],['#161b1d','Raised'],['#c6a56b','Brass'],['#eee9dc','Text'],['#91b9a3','Success']].map(([c,n])=>`<div class="swatch" style="background:${c}">${n}</div>`).join('')}</div><p class="muted" style="margin-top:14px">Opaque surfaces. Fine grain only on chrome. No blur, glass or animated scanlines.</p>`)}</div><div class="stack">${panel('Application scope',list([['Native frame','Already consumes ShellTheme','Token-ready','✓'],['Pane interiors','Hard-coded colors require migration','Work remaining','◇'],['Graph visuals','Same renderer and semantic colors','Adapter work','⌘'],['Qt / GTK / browser','Supported toolkit projections','Integration','▣'],['Lock / auth','Native security boundaries preserved','Protected','⬡']]),'No blanket success claim',true)}${note('Not a live Apply button.','This atlas packages the first palette and designs. Full native activation requires the migration and checks in the implementation plan.')}${panel('Theme policy',`<p class="muted">Validate → preview → atomic selection → owner projections → verify → keep previous version. One catalog, one selected palette, no per-pane stores.</p>`)}</div></div></div>`;
builders.launcher=()=>`<div class="overlay-panel">${panel('Open something',`<input type="search" class="local-filter" placeholder="Search apps, panes, files and knowledge…" aria-label="Launcher preview search" style="font-size:17px;min-height:50px"><div class="toolbar" style="margin-top:14px">${badge('LOCAL SEARCH')}${badge('NO MODEL REQUIRED','green')}<span class="grow"></span><kbd>Esc</kbd></div><div class="eyebrow" style="margin:20px 0 8px">PANES</div>${list([['Reader','Open the existing Article / Source viewer','Enter','▤'],['Graph','Knowledge · Memory · Code','Enter','◎'],['Terminal','Existing persistent session','Enter','›_']])}<div class="eyebrow" style="margin:20px 0 8px">APPLICATIONS</div>${list([['Code editor','Native registered desktop application','Enter','⌘'],['File manager','General filesystem','Enter','▣']])}<div class="annotation">Up/down selects a result; Enter activates the exact target. Free-form text is never executed as a shell command.</div>`,'Explicit search providers')}</div>`;
builders.workspaces=()=>`<div class="stack"><div class="toolbar">${button('Current workspace',true,'tab')}${button('Knowledge',false,'tab')}${button('Development',false,'tab')}<span class="grow"></span>${button('Save layout')}${button('Restore layout')}</div>${panel('Native window overview',`<div class="tile-layout" style="min-height:370px"><div class="tile tall"><span>Source</span>${tree('Architecture\nProjects\nEvidence')}<small>Native pane · exact identity</small></div><div class="tile wide"><span>Reader / native editor</span><small>Last active · Enter to focus</small></div><div class="tile"><span>Computer</span><small>Conversation</small></div><div class="tile wide"><span>Terminal</span><small>Persistent tmux session</small></div><div class="tile"><span>Graph</span><small>Same viewer</small></div></div>`,'Compositor Scene projection')}<div class="columns equal">${panel('Surfaces',list([['Main Surface','Wide work area','5120 × 1440 example','▣'],['Graph Surface','Auxiliary portrait workspace','1920 × 1200 logical','▣'],['Strip Surface','Compact controls and terminal','1920 × 550 logical','▣']]),'Topology examples, not applied',true)}${note('No second window manager.','Thumbnails and selection are presentation. Activation, close, resize and transfer use the existing token-bound adapter with a fresh target identity.')}</div></div>`;
builders.quick=()=>`<div class="columns"><div class="stack">${panel('Status drawer',`<div class="key-grid"><button data-action="tile" class="active">${icon('sound')} Sound<small>Output selected</small></button><button data-action="tile" class="active">⌁ Network<small>Connected</small></button><button data-action="tile">ᛒ Bluetooth<small>Available</small></button><button data-action="tile">◐ Focus<small>Do Not Disturb off</small></button><button data-action="tile">▣ Displays<small>3 example Surfaces</small></button><button data-action="tile">⏻ Power<small>Balanced</small></button></div><div class="setting-row"><div><strong>Output volume</strong><small>Existing PipeWire route</small></div><input type="range" value="52" aria-label="Sample output volume"></div><div class="setting-row"><div><strong>Media player</strong><small>Selected MPRIS participant</small></div>${button('Pause')}</div><div class="toolbar">${link('network','Network')}${link('audio','Sound')}${link('session','Session')}${link('appearance','Themes')}</div>`,'Model-independent controls')}</div><div class="stack">${panel('System tray',list([['Network status','NetworkManager projection','Connected','⌁'],['Bluetooth adapter','BlueZ projection','Available','◇'],['Notifications','mako remains the owner','Active','◐'],['Removable devices','UDisks2 projection','Review','▣']]),'StatusNotifierItem integration',true)}${note('Thin adapters.','The shell presents installed services. It must not bring up duplicate notification, network or audio daemons to obtain these controls.')}</div></div>`;
builders.notifications=()=>`<div class="columns"><div class="stack"><div class="toolbar"><h2>Notification center</h2><span class="grow"></span>${button('Clear reviewed')}${button('Settings')}</div>${panel('Today',list([['Review ready','Heimdall · one proposed knowledge change','5 min ago','⬡'],['File operation complete','Native file manager · target verified','14 min ago','✓'],['Application update available','Package metadata refreshed','23 min ago','▣']]),'Illustrative notifications',true)}${panel('Earlier',list([['Task finished','Darwin · completion receipt recorded','Yesterday','◇'],['Device disconnected','Audio route changed by service','Yesterday','♩']]),'Bounded history',true)}</div><div class="stack">${panel('Focus and privacy',`<div class="setting-row"><div><strong>Do Not Disturb</strong><small>Respect urgency and user-selected app rules.</small></div>${settingControl('toggle:off')}</div><div class="setting-row"><div><strong>Lock-screen details</strong><small>Hide message bodies while locked.</small></div>${settingControl('toggle:on')}</div><div class="setting-row"><div><strong>History retention</strong><small>Bounded local presentation, not AI memory.</small></div><select aria-label="History retention"><option>24 hours</option><option>Until logout</option></select></div>`)}${note('One notification server.','mako is already active. Add a compatible history/control projection, or plan an explicit owner handoff. Never start two servers.','info')}</div></div>`;
builders.audio=()=>`<div class="columns"><div class="stack">${panel('Output',`<div class="setting-row"><div><strong>Selected output</strong><small>Actual PipeWire route</small></div><select aria-label="Output"><option>Desktop speakers</option><option>System default</option></select></div><div class="setting-row"><div><strong>Volume</strong><small>No synthetic audio is played by this preview.</small></div><input type="range" value="48" aria-label="Volume"></div><div class="setting-row"><div><strong>Mute output</strong><small>Independent of microphone state.</small></div>${settingControl('toggle:off')}</div>`)}${panel('Application streams',list([['Browser','Playback stream','42% · sample','◎'],['Media player','Playback stream','65% · sample','▷'],['Computer speech','Existing Realtime output','Owner controlled','≈']]),'Per-stream volume / routing',true)}</div><div class="stack">${panel('Input',`<div class="setting-row"><div><strong>Microphone</strong><small>System source selection</small></div><select aria-label="Input"><option>System default</option><option>Microphone array</option></select></div><div class="setting-row"><div><strong>Input muted</strong><small>Display the real service state.</small></div>${settingControl('toggle:on')}</div>${note('No extra capture.','A level meter must consume supported service metering; this pane does not start a new microphone pipeline.')}`)}${panel('MPRIS player',`<h2>Selected media application</h2><p class="muted" style="margin-top:12px">Track identity and supported controls come from the chosen player.</p><div class="toolbar" style="margin-top:18px">${button('Previous')}${button('Play / pause')}${button('Next')}</div>`)}</div></div>`;
builders.displays=()=>`<div class="columns"><div class="stack">${panel('Display arrangement',`<div class="workspace-map"><div class="monitor main">Main display<span>Wide Surface · scale 1</span></div><div class="monitor side">Graph display<span>Scale 2</span></div></div><div class="annotation">Drag arrangement is a design illustration. Apply must use one validated compositor-adapter transaction.</div>`)}${panel('Selected display',`<div class="setting-row"><div><strong>Resolution and refresh</strong><small>Only modes reported by the real output.</small></div><select aria-label="Display mode"><option>Keep current mode</option><option>Preview supported mode</option></select></div><div class="setting-row"><div><strong>Scale</strong><small>Logical geometry remains explicit.</small></div><select aria-label="Display scale"><option>100%</option><option>200%</option></select></div><div class="setting-row"><div><strong>HDR / VRR</strong><small>Preserve accepted output-specific settings.</small></div><span class="mono gold">Keep current</span></div>`)}</div><div class="stack">${panel('Safe display change',`<div class="eyebrow">CONFIRMATION DESIGN</div><h2 style="margin-top:15px">Keep these display settings?</h2><p class="muted" style="margin-top:12px">Revert automatically if you cannot see or use the desktop. The real transaction owns the deadline.</p><div class="time" style="font-size:42px">15 s</div><div class="toolbar">${button('Keep settings',true)}${button('Revert now')}</div>`)}${note('Protected output contract.','No theme setting may alter HDR luminance, refresh rate, GPU routing, color management or accepted gaming settings.','info')}</div></div>`;
builders.shortcuts=()=>`<div class="stack"><div class="toolbar">${search('Find an action or key binding…')}${button('Review conflicts')}</div>${panel('Current native bindings',table(['Action','Binding','Owner','Policy'],[['Resize tile','Meta + Arrow','Compositor adapter','Existing'],['Translate tile','Ctrl + Meta + Arrow','Compositor adapter','Existing'],['Transfer Surface','Meta + Shift + Arrow','Compositor adapter','Existing'],['Close active native client','Inspect configured binding','Compositor adapter','Verify current binding'],['Cycle windows','Inspect configured binding','Compositor','Verify current binding'],['Independent recovery terminal','Installation-defined','Session integration','Protected'],['Global search','Choose after conflict review','Existing launcher','Proposed']]),'No shortcut changes applied',true)}<div class="columns equal">${panel('Edit binding',`<p class="muted">Select an action, capture a new key sequence in native code, detect conflicts and review the exact change before applying.</p><div class="toolbar" style="margin-top:18px">${button('Record shortcut')}${button('Restore default')}</div>`)}${note('Never steal recovery keys.','Keep the existing terminal and session-recovery paths available even when a model or pane is unavailable.')}</div></div>`;
builders.session=()=>`<div class="center-stage"><div class="secure-card"><div class="eyebrow">SESSION / EXPLICIT ACTION</div><h2>Leave the workspace?</h2><p>Check active work before ending the session. Locking keeps applications and tasks resident.</p><div class="stack">${button('Lock screen',true)}${button('Sign out')}${button('Restart computer')}${button('Power off')}</div><div class="annotation">Suspend is omitted for this installation’s current policy. This preview invokes none of these actions.</div></div></div>`;
builders.lock=()=>`<div class="center-stage" style="background:#02060c"><div class="secure-card" style="background:#02060c"><div class="eyebrow">OBSIDIAN GOLD / NATIVE LOCK DESIGN</div><div class="time">14:27</div><p>Thursday, 15 October · sample clock</p><h2>Workspace locked</h2><p>The production prompt appears only after the compositor reports a secure lock.</p><input type="text" disabled placeholder="Native PAM prompt only" aria-label="Disabled authentication illustration">${button('Unlock illustration',true)}<div class="annotation">Design only. No credentials are accepted. Existing opaque output coverage and the sole WlSessionLock/PAM owner remain unchanged.</div></div></div>`;
builders.login=()=>`<div class="center-stage"><div class="secure-card"><div class="eyebrow">OBSIDIENCE / FRESH SESSION</div><h2>Welcome back</h2><p>Select a local account and session through the installed greeter.</p><div class="setting-row"><div><strong>Local account</strong></div><span class="mono gold">Current user</span></div><div class="setting-row"><div><strong>Session</strong></div><span class="mono gold">Obsidience</span></div><input type="text" disabled placeholder="Authentication belongs to the native greeter" aria-label="Disabled greeter illustration" style="margin-top:20px">${button('Sign in illustration',true)}<div class="annotation">greetd owns login. This is not the active-session lock and cannot collect credentials.</div></div></div>`;
builders.permissions=()=>`<div class="center-stage"><div class="secure-card"><div class="eyebrow">SYSTEM AUTHORIZATION / NATIVE ONLY</div><h2>Authorize a system change</h2><p>A requesting application must identify the exact privileged operation before authentication.</p><dl class="permission-details"><dt>Requester</dt><dd>Verified application identity</dd><dt>Action</dt><dd>Install selected system packages</dd><dt>Authority</dt><dd>polkit</dd><dt>Scope</dt><dd>This operation only</dd></dl><input type="text" disabled placeholder="Trusted native authentication agent" aria-label="Disabled authorization illustration"><div class="toolbar">${button('Cancel')}${button('Authorize illustration',true)}</div><div class="annotation">No credential input in this atlas. Graphical agent availability and actual policy enforcement require native acceptance.</div></div></div>`;
builders.files=()=>`<div class="stack"><div class="toolbar">${button('Back')}${button('Up')}<input aria-label="Sample file location" value="Home / Projects" class="grow">${button('Search')}${button('View')}</div><div class="columns" style="grid-template-columns:210px minmax(0,1fr)">${panel('Places',list([['Home','','','⌂'],['Documents','','','▤'],['Projects','','Selected','⌘'],['Downloads','','','↓'],['Devices','','','▣'],['Trash','','','◇']]),'Native file manager',true)}<div class="stack">${panel('Projects',`<div class="card-grid">${['Obsidience','Research','Notes','Assets','Archive','Designs'].map(n=>`<div class="card filterable"><span class="glyph">${icon('source')}</span><h3>${n}</h3><p>Illustrative folder<br>Native filesystem identity</p></div>`).join('')}</div>`,'Upstream file operations')}${panel('Transfer conflict',`<div class="toolbar"><div class="grow"><h3>A file with this name already exists</h3><small>Show source/destination path, size and modification time before replacing.</small></div>${button('Keep both')}${button('Skip')}${button('Replace')}</div>`)}${note('Reuse the file engine.','Theme and launch a maintained native file manager. Do not route general file operations through the Article or Source writer.')}</div></div></div>`;
builders['file-dialog']=()=>`<div class="overlay-panel" style="max-width:930px">${panel('Save a file',`<div class="toolbar">${button('Up')}<input class="grow" aria-label="Sample save location" value="Home / Documents">${button('New folder')}</div>${table(['Name','Type','Modified'],[['Design notes','Folder','Today'],['Reference material','Folder','Yesterday'],['theme-plan.md','Markdown document','Today']])}<div class="setting-row"><div><strong>Filename</strong></div><input aria-label="Sample filename" value="theme-plan.md"></div><div class="setting-row"><div><strong>File type</strong></div><select aria-label="Sample type"><option>Markdown document (*.md)</option><option>All files</option></select></div><div class="toolbar">${badge('XDG PORTAL FILE CHOOSER')}<span class="grow"></span>${button('Cancel')}${button('Save illustration',true)}</div><div class="annotation">Sandbox authorization, overwrite confirmation and returned file handles belong to the existing portal backend.</div>`,'Trusted existing chooser')}</div>`;
builders.clipboard=()=>`<div class="columns"><div class="stack">${panel('Clipboard history',`${search('Search retained clips…')}<div style="margin-top:14px">${list([['History is paused','Collection is off until deliberately enabled.','Private by default','○'],['Pinned example','A deliberate non-sensitive snippet.','Sample only','▤'],['Design note','One visual authority; no per-pane theme stores.','Sample only','◇']])}</div><div class="toolbar" style="margin-top:16px">${button('Enable local history')}${button('Clear history')}${button('Pause')}</div>`,'Opt-in extension')}${note('No AI ingestion.','Clipboard content does not automatically become model context or permanent knowledge.','info')}</div><div class="stack">${panel('Retention controls',`<div class="setting-row"><div><strong>Collect history</strong><small>Basic copy/paste works regardless.</small></div>${settingControl('toggle:off')}</div><div class="setting-row"><div><strong>Hide while locked</strong><small>Never expose private text at unlock.</small></div>${settingControl('toggle:on')}</div><div class="setting-row"><div><strong>Maximum items</strong><small>Bounded local storage.</small></div><span class="mono gold">50</span></div><div class="annotation">Secret hints and private selections must be handled according to provider support. Do not promise universal password detection.</div>`)}</div></div>`;
builders.capture=()=>`<div class="columns"><div class="stack">${panel('Capture source',`<div class="toolbar">${button('Window',true,'tab')}${button('Region',false,'tab')}${button('Display',false,'tab')}</div><div class="tile-layout" style="min-height:270px;grid-template-columns:1fr 1fr"><div class="tile"><span>Selected application</span><small>Exact native window identity</small></div><div class="tile"><span>Current Surface</span><small>Preview bounds before capture</small></div></div><div class="setting-row"><div><strong>Destination</strong><small>Explicit local save path or share operation.</small></div><select aria-label="Capture destination"><option>Pictures / Screenshots</option><option>Ask each time</option></select></div><div class="toolbar">${button('Capture illustration',true)}${button('Cancel')}</div>`,'Existing capture / portal owner')}</div><div class="stack">${panel('Recording and sharing',`<p>Recording and screen sharing have visible session indicators and a real stop/revoke control.</p><div class="toolbar" style="margin-top:18px">${badge('NOT RECORDING')}${button('Review active sessions')}</div><div class="annotation">A portal session owns source selection, stream lifetime and PipeWire handles. No hidden capture daemon is added.</div>`)}${note('Privacy-sensitive surface.','Never share an entire display when one selected window is enough. Do not include hidden or locked windows in previews.','info')}</div></div>`;
builders.calendar=()=>`<div class="columns equal">${panel('October 2026',`<div class="toolbar"><h2>Thursday, 15 October</h2><span class="grow"></span>${button('Today')}</div><div class="calendar">${['M','T','W','T','F','S','S'].map(x=>`<span>${x}</span>`).join('')}${Array.from({length:35},(_,i)=>{let d=i-2;return d<1||d>31?'<span></span>':`<button type="button" class="${d===15?'today':''}" data-action="calendar">${d}</button>`;}).join('')}</div>`,'System date, illustrative snapshot')}${panel('Agenda',`<div class="time" style="font-size:46px">14:27</div><p class="muted">Local timezone is shown by the system clock.</p><div class="large-empty" style="min-height:210px;border:0"><span class="symbol">◷</span><h3>No calendar source connected</h3><p>The month view works offline. Events appear only from an explicitly connected source.</p></div><div class="toolbar">${button('Manage calendar sources')}${link('defaults','Timezone settings')}</div>`,'No invented appointments')}</div>`;
builders.storage=()=>`<div class="columns"><div class="stack">${panel('Devices',list([['System volume','Mounted · current filesystem','Protected','▣'],['Data volume','Mounted · storage owner reports state','In use','▣'],['Removable device','Example device · exact identity required','Review','◇']]),'UDisks2 presentation',true)}${panel('Selected volume',`<div class="metrics" style="grid-template-columns:1fr 1fr">${metric('USED','128 GB','Illustrative')}${metric('CAPACITY','512 GB','Illustrative')}</div><div class="permission-details"><dt>Mount</dt><dd>Provider-reported path</dd><dt>Filesystem</dt><dd>Provider-reported type</dd><dt>Activity</dt><dd>Check holders before eject</dd></div><div class="toolbar">${button('Open in Files')}${button('Safely eject')}</div>`)}</div><div class="stack">${note('Exact device binding.','An eject or mount command must target a fresh, verified device identity, not a label that may refer to another disk.','info')}${panel('Destructive operations',`<p class="muted">Formatting, partition changes and erasure are intentionally absent from the quick surface. Open maintained privileged tooling with explicit confirmation.</p>`)}${panel('Failure presentation',list([['Busy','Explain open files and active transfers','Wait','◇'],['Removed','Do not replay pending writes','Unavailable','○'],['Permission required','Use native authentication','Review','⬡']]),'',true)}</div></div>`;
function renderBody(s){const fn=builders[s.kind];return fn?fn(s):note('Design unavailable','This route has no implementation.');}
let current=screens[0], toastTimer;
function showToast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function showNotes(){const s=current;$('#notes-content').innerHTML=`<div class="eyebrow">IMPLEMENTATION / ${esc(s.status)}</div><h2>${esc(s.title)}</h2><p><strong>Stable pane identity:</strong> ${esc(s.pane||'Composition or transient surface')}</p><p><strong>Existing or proposed path:</strong><br><code>${esc(s.source)}</code></p><p><strong>Owner:</strong> ${esc(s.owner)}</p><p><strong>Workflow:</strong> ${esc(s.workflow)}</p><p><strong>Acceptance boundary:</strong> ${esc(s.acceptance)}</p><p class="muted">All displayed records are illustrative. Controls make no system requests. Native implementation is mapped separately in the package Markdown.</p>`;$('#notes').showModal();}
function render(){let id=location.hash.slice(1)||'desktop';current=screens.find(s=>s.id===id)||screens[0];const s=current;$('#screen-picker').value=s.id;$('#position').textContent=String(screens.indexOf(s)+1).padStart(2,'0')+' / '+screens.length;
 $('#screen-heading').innerHTML=`<div><div class="eyebrow">${esc(s.group)} / ${esc(s.pane||'SHELL COMPOSITION')}</div><h1>${esc(s.title)}</h1><p>${esc(s.workflow)}</p></div><div class="heading-meta">${badge(s.status,s.status==='Existing'?'green':'blue')}<small>Obsidian Gold · illustrative design</small></div>`;
 const state=$('#state-picker').value;
 if(state==='empty'||state==='unavailable'){$('#content').innerHTML=`<div class="large-empty"><span class="symbol">${state==='empty'?'◇':'○'}</span><div class="eyebrow">${esc(s.title)}</div><h2>${state==='empty'?'Nothing to show yet':'This service is unavailable'}</h2><p>${state==='empty'?'Keep the current selection, navigation and relevant next action visible. An empty result is not a connection failure.':'Preserve the last accepted view with a stale label where appropriate. Show the actual service error; do not invent healthy measurements or start a restart loop.'}</p><div class="toolbar">${button(state==='empty'?'Choose a source':'Retry explicitly',true)}${button('Implementation notes',false,'spec')}</div></div>`;}else{$('#content').innerHTML=(state==='approval'?note('Approval required.','Show the exact target, requested change, consequences and required native authorization before proceeding. This preview sends no action.')+'<div style="height:12px"></div>':'')+renderBody(s);}
 document.querySelectorAll('.nav-link').forEach(el=>el.classList.toggle('active',el.getAttribute('href')==='#'+s.id));$('#content').scrollTop=0; document.querySelector('.nav-link.active')?.scrollIntoView({block:'nearest'}); document.querySelectorAll('.setting-row').forEach(row=>row.querySelectorAll('input,select,button.toggle').forEach(control=>control.setAttribute('aria-label',(row.querySelector('strong')?.textContent||'Setting')+' (design preview)')));$('#status-line').textContent='PREVIEW · '+s.status+' · No system actions';document.title=s.title+' | Obsidian Gold';window.__previewReady=s.id;
}
const groups=[...new Set(screens.map(s=>s.group))];
$('#screen-picker').innerHTML=groups.map(g=>`<optgroup label="${esc(g)}">${screens.filter(s=>s.group===g).map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</optgroup>`).join('');
$('#navigation').innerHTML=groups.map(g=>`<div class="nav-group">${esc(g)}</div>${screens.filter(s=>s.group===g).map(s=>`<a class="nav-link" href="#${esc(s.id)}"><span class="n">${String(screens.indexOf(s)+1).padStart(2,'0')}</span><span>${esc(s.title.replace(/^[^/]*\/ /,''))}</span>${s.status==='Existing'?'':'<span class="new-dot"></span>'}</a>`).join('')}`).join('');
$('#screen-picker').addEventListener('change',e=>location.hash=e.target.value);$('#state-picker').addEventListener('change',render);$('#spec-button').addEventListener('click',showNotes);$('#close-notes').addEventListener('click',()=>$('#notes').close());$('#density').addEventListener('click',e=>{document.body.classList.toggle('compact');e.target.textContent=document.body.classList.contains('compact')?'Compact density':'Comfortable density';});$('#find-screen').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.nav-link').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q));});
document.addEventListener('input',e=>{if(e.target.matches('.local-filter')){const q=e.target.value.toLowerCase();$('#content').querySelectorAll('.filterable').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='spec'){showNotes();return;}if(a==='toggle'){b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'));showToast('Preview state changed. No device or system setting was written.');return;}if(a==='tab'){b.parentElement.querySelectorAll('.tab,.primary').forEach(x=>x.classList.remove('active','primary'));b.classList.add(b.classList.contains('tab')?'active':'primary');showToast('Tab styling preview. Named subviews have separate entries in the surface selector.');return;}if(a==='tile'){b.classList.toggle('active');showToast('Tile state preview only. No system service was called.');return;}if(a==='calendar'){b.closest('.calendar').querySelectorAll('.today').forEach(x=>x.classList.remove('today'));b.classList.add('today');return;}showToast('Design preview only: '+b.textContent.trim()+'. No command was sent.');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#toast').style.display='none';}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#find-screen').focus();}});
window.addEventListener('hashchange',render);const query=new URLSearchParams(location.search); if(query.has('render'))document.body.classList.add('render'); if(['ready','empty','unavailable','approval'].includes(query.get('state')))$('#state-picker').value=query.get('state'); render();
